embedding.query:
query ($id: ID) {
  Person(id: $id) {
    name
    gender
    birth_year
    side
    faction
    quote
    height
    mass
    hair_color
    eye_color
    homeworld {
      name
    }
    species {
      name
    }
    films {
      title
    }
    died_in_film {
      title
    }
  }
}

embedding.template:
{{name}} — {{#each species}}{{this.name}} {{/each}}{{gender}} character{{#if homeworld}} from {{homeworld.name}}{{/if}}{{#if side}}, {{side}} side{{/if}}{{#if faction}} of the {{faction}}{{/if}}. Born {{birth_year}}.
{{#if height}}Height {{height}} m, mass {{mass}} kg, hair {{hair_color}}, eyes {{eye_color}}.{{/if}}
{{#if quote}}Known for saying: "{{quote}}"{{/if}}
{{#each films}}Appears in "{{this.title}}". {{/each}}{{#if died_in_film}}Died in "{{died_in_film.title}}".{{/if}}

